const out = {}
try { out.root = await bash({ command: 'ls -la', description: 'List repo root' }) } catch (e) { out.root = String(e) }
try { out.branch = await bash({ command: 'git log --oneline -8 && git status --short', description: 'Recent commits and status' }) } catch (e) { out.branch = String(e) }
const csproj = (await glob({ pattern: '**/*.csproj' })).split('\n').filter(Boolean)
const sln = (await glob({ pattern: '**/*.sln' })).split('\n').filter(Boolean)
const pkg = (await glob({ pattern: '**/package.json' })).split('\n').filter(Boolean).filter(p => !p.includes('node_modules'))
out.projects = { csproj, sln, pkg }
return out

const files = (await glob({ pattern: 'src/**/*.ts' })).split('\n').filter(Boolean)
const tests = (await glob({ pattern: 'test/**/*.ts' })).split('\n').filter(Boolean)
const byDir = {}
let totalLines = 0
const sizes = []
for (const f of files) {
  const t = await read(f)
  const lines = t.split('\n').length
  totalLines += lines
  sizes.push([f.replace(/^.*CodingAgent[\\/]/, ''), lines])
  const dir = f.replace(/^.*[\\/]src[\\/]/, 'src/').split(/[\\/]/).slice(0, 3).join('/')
  byDir[dir] = (byDir[dir] || 0) + lines
}
sizes.sort((a, b) => b[1] - a[1])
return {
  counts: { srcFiles: files.length, testFiles: tests.length, totalLines },
  byDir: Object.entries(byDir).sort((a,b)=>b[1]-a[1]),
  biggest: sizes.slice(0, 20),
  tests: tests.map(t => t.replace(/^.*CodingAgent[\\/]/, ''))
}

const src = (await glob({ pattern: 'src/**/*.ts' })).split('\n').filter(Boolean)
const test = (await glob({ pattern: 'test/**/*.ts' })).split('\n').filter(Boolean)
const all = [...src, ...test]

const rel = f => f.replace(/^.*CodingAgent[\\/]/, '').replace(/\\/g, '/')
const text = {}
for (const f of all) text[f] = await read(f)

// 1. collect exported symbols per src file
const defs = new Map() // symbol -> [files]
const declRe = /^\s*export\s+(?:declare\s+)?(?:async\s+)?(?:function|class|const|let|var|interface|type|enum)\s+([A-Za-z_$][\w$]*)/gm
const listRe = /^\s*export\s*\{([^}]*)\}/gm
for (const f of src) {
  const t = text[f]
  const found = new Set()
  let m
  while ((m = declRe.exec(t))) found.add(m[1])
  while ((m = listRe.exec(t))) for (const p of m[1].split(',')) {
    const n = p.trim().split(/\s+as\s+/).pop().trim()
    if (/^[A-Za-z_$][\w$]*$/.test(n)) found.add(n)
  }
  for (const n of found) {
    if (!defs.has(n)) defs.set(n, [])
    defs.get(n).push(f)
  }
}

// 2. identifier usage per file (excluding its own definition site)
const idents = {}
for (const f of all) {
  const s = new Set()
  const t = text[f].replace(/\/\/[^\n]*/g, ' ').replace(/\/\*[\s\S]*?\*\//g, ' ')
  let m
  const re = /[A-Za-z_$][\w$]*/g
  while ((m = re.exec(t))) s.add(m[0])
  idents[f] = s
}

const known = new Set(['activate', 'deactivate'])
const unusedAnywhere = []
const srcOnlyInTests = []
for (const [sym, owners] of defs) {
  if (known.has(sym)) continue
  let usedInSrc = false, usedInTest = false
  for (const f of src) if (!owners.includes(f) && idents[f].has(sym)) { usedInSrc = true; break }
  for (const f of test) if (idents[f].has(sym)) { usedInTest = true; break }
  if (!usedInSrc && !usedInTest) unusedAnywhere.push([sym, owners.map(rel)])
  else if (!usedInSrc && usedInTest) srcOnlyInTests.push([sym, owners.map(rel)])
}

// 3. src modules with no test that references any of their exports
const untested = []
for (const f of src) {
  const mine = [...defs].filter(([, o]) => o.includes(f)).map(([s]) => s)
  if (!mine.length) continue
  const covered = test.some(tf => mine.some(s => idents[tf].has(s)))
  if (!covered) untested.push([rel(f), mine.length, text[f].split('\n').length])
}
untested.sort((a, b) => b[2] - a[2])

return {
  totals: { exportedSymbols: defs.size, unusedAnywhere: unusedAnywhere.length, testOnly: srcOnlyInTests.length, untestedModules: untested.length },
  unusedAnywhere: unusedAnywhere.slice(0, 60),
  testOnly: srcOnlyInTests.slice(0, 30),
  untestedTop: untested.slice(0, 25)
}

