input.script:
const src = (await glob({ pattern: 'src/**/*.ts' })).split('\n').filter(Boolean)
const test = (await glob({ pattern: 'test/**/*.ts' })).split('\n').filter(Boolean)
const rel = f => f.replace(/^.*CodingAgent[\\/]/, '').replace(/\\/g, '/')
const text = {}
for (const f of [...src, ...test]) text[f] = await read(f)

// any non-ts assets that could reference symbols dynamically?
const others = (await glob({ pattern: 'src/**/*.{html,css,json,js}' })).split('\n').filter(Boolean)

const declRe = /^\s*export\s+(?:declare\s+)?(?:async\s+)?(?:function|class|const|let|var|interface|type|enum)\s+([A-Za-z_$][\w$]*)/gm
const defs = new Map()
for (const f of src) { let m; const t = text[f]; declRe.lastIndex = 0
  while ((m = declRe.exec(t))) { if (!defs.has(m[1])) defs.set(m[1], []); defs.get(m[1]).push(f) } }

const idents = {}
for (const f of [...src, ...test]) {
  const s = new Map()
  const t = text[f].replace(/\/\/[^\n]*/g, ' ').replace(/\/\*[\s\S]*?\*\//g, ' ')
  let m; const re = /[A-Za-z_$][\w$]*/g
  while ((m = re.exec(t))) s.set(m[0], (s.get(m[0]) || 0) + 1)
  idents[f] = s
}

const deadNoRefs = [], internalOnly = [], barrelOnly = []
for (const [sym, owners] of defs) {
  if (sym === 'activate' || sym === 'deactivate') continue
  if (owners.length !== 1) continue
  const own = owners[0]
  let external = false
  for (const f of [...src, ...test]) if (f !== own && idents[f].has(sym)) { external = true; break }
  if (external) continue
  const selfCount = idents[own].get(sym) || 0
  const entry = { sym, file: rel(own), selfCount }
  if (selfCount <= 1) deadNoRefs.push(entry)      // only the declaration itself
  else internalOnly.push(entry)
}

// kind of each dead symbol + line of declaration
const detail = []
for (const d of deadNoRefs) {
  const f = src.find(s => rel(s) === d.file)
  const lines = text[f].split('\n')
  const i = lines.findIndex(l => new RegExp(`^\\s*export\\s+(declare\\s+)?(async\\s+)?(function|class|const|let|var|interface|type|enum)\\s+${d.sym}\\b`).test(l))
  const kind = (lines[i] || '').match(/(function|class|const|let|var|interface|type|enum)/)?.[1]
  detail.push({ ...d, line: i + 1, kind, code: (lines[i] || '').trim().slice(0, 100) })
}
const byKind = {}
for (const d of detail) byKind[d.kind] = (byKind[d.kind] || 0) + 1

return {
  nonTsAssets: others.map(rel),
  totals: { deadNoRefs: deadNoRefs.length, internalOnly: internalOnly.length, byKind },
  internalOnly: internalOnly.map(x => `${x.file}:${x.sym} (${x.selfCount}x)`),
  dead: detail.map(d => `${d.file}:${d.line} [${d.kind}] ${d.sym}`)
}

const syms = ['SessionEventType','stepChoices','docsEvaluationKickoff','DOCS_MAP_TIME_BOUND_MS','docsMapDir','summaryFile','docsIndexPath','INDEX_DIR','REPO_MAP_TIME_BOUND_MS','commentsFor','summaryMapPath','newestSource','publicTypeCount','MAX_RESPONSE_BYTES','nodeOnPath']
const res = {}
for (const s of syms) {
  let out
  try {
    out = await bash({ command: `git grep -n -w "${s}" -- src test docs plan scripts package.json`, description: `Find references to ${s}` })
  } catch (e) { out = '(no matches)' }
  res[s] = out.split('\n').filter(Boolean)
}
const pkg = JSON.parse(await read('package.json'))
return { scripts: pkg.scripts, refs: res }

